function getGithubCopilotTranslation(key, lang) {
    if (githubCopilotTranslations[lang] && githubCopilotTranslations[lang][key]) {
        return githubCopilotTranslations[lang][key];
    }
    if (githubCopilotTranslations.en && githubCopilotTranslations[lang][key]) {
        return githubCopilotTranslations.en[key];
    }
    return null;
}

function applyGithubCopilotTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.github-copilot.') || key.startsWith('review.common.') || key.startsWith('nav.'))) {
            const translation = getGithubCopilotTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyGithubCopilotTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyGithubCopilotTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyGithubCopilotTranslations(currentLang);
}


